using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
namespace CityForge.Editor {
[InitializeOnLoad] public static class PondFloraPlantingStudy {
const string W="/Users/joelinstrum/Documents/Codex/2026-10-09/pl/work/pond-planting/", O="/Users/joelinstrum/Documents/Codex/2026-10-09/pl/outputs/", A="Assets/CityForge/Art/Environment/NaturalTerrainLab/";
static double due;static int frame;static PondFloraPlantingStudy(){EditorApplication.update+=Tick;}
static bool Take(string n){if(!File.Exists(W+n))return false;File.Delete(W+n);return true;}
static void Tick(){if(EditorApplication.isCompiling)return;try{if(!EditorApplication.isPlaying&&Take("build"))Build();if(EditorApplication.isPlaying&&Take("capture")){EditorApplication.isPaused=false;frame=0;due=EditorApplication.timeSinceStartup+5;}if(due>0&&EditorApplication.timeSinceStartup>due){Capture();frame++;due=frame<2?EditorApplication.timeSinceStartup+2:0;}}catch(Exception e){due=0;File.WriteAllText(O+"PondPlanting_Error.txt",e.ToString());Debug.LogException(e);}}
static Bounds Bounds(GameObject go){var rs=go.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
static void Build(){var scene=EditorSceneManager.OpenScene(A+"PondFloraSoftGrass.unity");UnityEngine.Object.DestroyImmediate(GameObject.Find("Pond edge low flora experiment"));
var terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>(FindObjectsInactive.Include);var root=new GameObject("Pond edge low flora experiment");var names=new[]{"Cord Leaf A1","Silk Vein A1","Rift Weed A2","Alstilbe","Fleeting Sage B2"};var sources=names.Select(n=>AssetDatabase.LoadAssetAtPath<GameObject>("Assets/(PBR) Low-Grow Flora/Prefabs/Med Res/"+n+".prefab")).ToArray();var mats=new Dictionary<Material,Material>();var rng=new System.Random(721);int count=0;var report=new List<string>();
foreach(var s in sources){var temp=UnityEngine.Object.Instantiate(s);report.Add(s.name+" source dimensions "+Bounds(temp).size);UnityEngine.Object.DestroyImmediate(temp);}
for(int j=0;j<9;j++){float angle=.3f+j*.70f;for(int k=0;k<48;k++){float a=angle+((float)rng.NextDouble()-.5f)*.46f;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));Vector3 pos=Vector3.zero;bool found=false;for(float radius=12;radius<68;radius+=.25f){pos=new Vector3(133,0,130)+dir*radius;float y=terrain.SampleHeight(pos)+terrain.transform.position.y;if(y>6.95f){pos+=dir*(.2f+(float)rng.NextDouble()*6f);pos.y=terrain.SampleHeight(pos)+terrain.transform.position.y;if(pos.y<8.6f){found=true;}break;}}if(!found)continue;
var go=(GameObject)PrefabUtility.InstantiatePrefab(sources[(j+k)%5]);go.transform.SetParent(root.transform);go.name=names[(j+k)%5]+" bank patch "+j;go.transform.rotation=Quaternion.Euler(0,(float)rng.NextDouble()*360,0);go.transform.localScale*= (((j+k)%5==2||(j+k)%5==4)?.20f+(float)rng.NextDouble()*.14f:.60f+(float)rng.NextDouble()*.45f)/Bounds(go).size.y;go.transform.position=pos;go.transform.position+=Vector3.up*(pos.y-Bounds(go).min.y-.025f);
foreach(var r in go.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(old=>{if(!mats.TryGetValue(old,out var m)){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.name="PondPlanting_"+old.name;var tex=old.HasProperty("_BaseMap")?old.GetTexture("_BaseMap"):old.GetTexture("_MainTex");m.SetTexture("_BaseMap",tex);m.SetColor("_BaseColor",new Color(.66f,.73f,.59f,1));if(old.HasProperty("_BumpMap"))m.SetTexture("_BumpMap",old.GetTexture("_BumpMap"));m.SetFloat("_Smoothness",.1f);m.SetFloat("_Cull",0);m.SetFloat("_AlphaClip",1);m.SetFloat("_Cutoff",.35f);m.EnableKeyword("_ALPHATEST_ON");m.renderQueue=2450;m.enableInstancing=true;AssetDatabase.DeleteAsset(A+m.name+".mat");AssetDatabase.CreateAsset(m,A+m.name+".mat");mats[old]=m;}return m;}).ToArray();r.shadowCastingMode=ShadowCastingMode.TwoSided;}count++;}}
AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,A+"PondFloraPlanting.unity");report.Add(count+" plants in 9 discontinuous patches; upright height .60–1.05m, rosettes .20–.34m. Source package preserved; shared URP material copies. Ground brightness variation 32% reduced to 6%, random bare soil 22% to 3.5%, dry tint 30% to 8%, broad tint spread reduced. Water, waves, lighting and mature trees unchanged.");File.WriteAllLines(O+"PondPlanting_Changes.txt",report);Debug.Log("POND FLORA READY "+count);}
static void Capture(){var c=GameObject.Find("Meadow presentation camera").GetComponent<Camera>();c.orthographicSize=40;c.transform.position=new Vector3(133,8,130)-c.transform.forward*110;c.ResetProjectionMatrix();var rt=new RenderTexture(1920,1080,24);rt.Create();var prev=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(c,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var t=new Texture2D(1920,1080,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1920,1080),0,0);t.Apply();File.WriteAllBytes(O+"PondFloraPlanting_"+frame+".png",t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}finally{RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
}}
